from parsing import parse_bool
from settings import load
import unittest

class Checks(unittest.TestCase):
    def test_false_values(self):
        for value in ("false", " NO ", "0"): self.assertFalse(parse_bool(value))
    def test_true_values(self):
        for value in ("true", " YES ", "1"): self.assertTrue(parse_bool(value))
    def test_default(self):
        self.assertEqual(load({}), {"enabled": False, "timeout": 30})
    def test_converted(self):
        self.assertEqual(load({"enabled": "false", "timeout": "12"}), {"enabled": False, "timeout": 12})
    def test_invalid(self):
        with self.assertRaises(ValueError): parse_bool("maybe")
        with self.assertRaises(ValueError): load({"timeout": "0"})
        with self.assertRaises(ValueError): load({"timeout": "bad"})
